namespace ToneCustoms.ShellStudio.Core;
public sealed class RoomGenerator { readonly GeometryService g=new();public IEnumerable<SceneObject> Generate(Vec3 center,float width,float depth,float height=3,float thickness=.15f,int floor=0){var z=center.Z+height/2;yield return WithFloor(g.Wall(new(center.X,center.Y-depth/2,z),width,height,thickness),floor);yield return Rotate(WithFloor(g.Wall(new(center.X+width/2,center.Y,z),depth,height,thickness),floor),90);yield return WithFloor(g.Wall(new(center.X,center.Y+depth/2,z),width,height,thickness),floor);yield return Rotate(WithFloor(g.Wall(new(center.X-width/2,center.Y,z),depth,height,thickness),floor),90);yield return WithFloor(g.Floor(new(center.X,center.Y,center.Z),width,depth),floor);yield return WithFloor(g.Ceiling(new(center.X,center.Y,center.Z+height),width,depth),floor);}static SceneObject WithFloor(SceneObject o,int f){o.FloorLevel=f;return o;}static SceneObject Rotate(SceneObject o,float z){o.Rotation.Z=z;return o;} }
